-- player param wheel and param sliders.

local gameParamsGui={}

local TweenService=game:GetService("TweenService")

local defaultSelectedPage="speed"

local dialWidth=96
local dialHeight=96
local dialSideGap=14
local dialGlowPad=6
local dialInnerRadius=0.22
local dialOuterRadius=0.43
local dialGapDegrees=8
local dialGlowLayers={
	{pad=2,z=5},
	{pad=4,z=4},
}
local paramsPageHeight=176
local pageTween=TweenInfo.new(0.22,Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
local paintTween=TweenInfo.new(0.16,Enum.EasingStyle.Quad,Enum.EasingDirection.Out)
local glowTween=TweenInfo.new(0.34,Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
local pageOrder={"speed","gravity","stamina"}
local pageIndex={speed=1,gravity=2,stamina=3}
local dialSectors={
	{key="gravity",start=30,finish=150},
	{key="speed",start=150,finish=270},
	{key="stamina",start=270,finish=390},
}
local dialMidAngles={gravity=90,speed=210,stamina=330}
local dialAssetVersion="v12"
local dialSliceData={
	speed={x=0,y=0,w=1,h=1,hex=[[]],glowHex=[[]]},
	gravity={x=0,y=0,w=1,h=1,hex=[[]],glowHex=[[]]},
	stamina={x=0,y=0,w=1,h=1,hex=[[]],glowHex=[[]]},
}

local dialCenterCapHex=nil

local function destroyControl(control)
	if control and type(control.destroy)=="function" then
		pcall(control.destroy)
	elseif control and type(control.Destroy)=="function" then
		pcall(control.Destroy)
	end
end

local function normalizePageKey(value)
	local raw=tostring(value or defaultSelectedPage):lower():gsub("%s+","")

	if raw=="speed" or raw=="1" then
		return"speed"
	elseif raw=="gravity" or raw=="jump" or raw=="gravityjump" or raw=="gravity/jump" or raw=="2" then
		return"gravity"
	elseif raw=="stamina" or raw=="3" then
		return"stamina"
	end

	return defaultSelectedPage
end

local function themeColor(theme,key,fallback)
	return (theme and theme[key]) or fallback
end

local function brightenColor(color,amount)
	amount=math.clamp(tonumber(amount) or 0,0,1)
	return color:Lerp(Color3.new(1,1,1),amount)
end

local function darkenColor(color,amount)
	amount=math.clamp(tonumber(amount) or 0,0,1)
	return color:Lerp(Color3.new(0,0,0),amount)
end

local function colorLuminance(color)
	return color.R*0.299+color.G*0.587+color.B*0.114
end

local function atan2(y,x)
	if x>0 then
		return math.atan(y/x)
	elseif x<0 and y>=0 then
		return math.atan(y/x)+math.pi
	elseif x<0 then
		return math.atan(y/x)-math.pi
	elseif y>0 then
		return math.pi*0.5
	elseif y<0 then
		return -math.pi*0.5
	end

	return 0
end

local function inAngleRange(angle,startAngle,finishAngle)
	local start=startAngle+dialGapDegrees
	local finish=finishAngle-dialGapDegrees

	if finish>360 then
		return angle>=start or angle<=(finish-360)
	end

	return angle>=start and angle<=finish
end

local function decodeHex(hex)
	hex=tostring(hex or ""):gsub("%s+","")
	local bytes=table.create(math.floor(#hex/2))

	for index=1,#hex,2 do
		bytes[#bytes+1]=string.char(tonumber(hex:sub(index,index+1),16) or 0)
	end

	return table.concat(bytes)
end

local sliceAssetCache=nil
local sliceAssetResolved=false

local function getDialSliceAssets()
	if sliceAssetResolved then
		return sliceAssetCache
	end

	sliceAssetResolved=true

	if type(writefile)~="function" or type(getcustomasset)~="function" then
		return nil
	end

	local assets={}

	for pageKey,data in pairs(dialSliceData) do
		local path="params_circledial_"..dialAssetVersion.."_"..pageKey..".png"
		local glowPath="params_circledial_"..dialAssetVersion.."_"..pageKey.."_glow.png"
		local writeOk=pcall(writefile,path,decodeHex(data.hex))
		if not writeOk then
			return nil
		end

		local glowWriteOk=pcall(writefile,glowPath,decodeHex(data.glowHex))
		if not glowWriteOk then
			return nil
		end

		local assetOk,asset=pcall(getcustomasset,path)
		if not assetOk or type(asset)~="string" then
			return nil
		end

		local glowAssetOk,glowAsset=pcall(getcustomasset,glowPath)
		if not glowAssetOk or type(glowAsset)~="string" then
			return nil
		end

		assets[pageKey]={slice=asset,glow=glowAsset}
	end

	if type(dialCenterCapHex)=="string" and #dialCenterCapHex>0 then
		local centerPath="params_circledial_"..dialAssetVersion.."_center.png"
		local centerWriteOk=pcall(writefile,centerPath,decodeHex(dialCenterCapHex))
		if centerWriteOk then
			local centerAssetOk,centerAsset=pcall(getcustomasset,centerPath)
			if centerAssetOk and type(centerAsset)=="string" then
				assets._center=centerAsset
			end
		end
	end

	sliceAssetCache=assets
	return assets
end

function gameParamsGui.GetDialSliceAssets()
	return getDialSliceAssets()
end

function gameParamsGui.new(app,parent)
	local runtime=app.Page1GameParamsLogicModule.new(app)
	local make=app.New
	local colors=app.colors or {}
	local safeDisconnect=app.safeDisconnect
	local makeSection=app.makeSection
	local buildSlider=app.buildSlider
	local buildToggleLabel=app.buildToggleLabel
	local buildToggleRow=app.buildToggleRow
	local state=runtime.GetState and runtime.GetState() or app.State
	local api={}
	local gravitySlider=nil
	local speedSlider=nil
	local staminaRegenSlider=nil
	local staminaDepleteSlider=nil
	local jumpSlider=nil
	local diveSlider=nil
	local settingToggles={}
	local dialWrap=nil
	local pageClip=nil
	local pageFrames={}
	local dialImages={}
	local dialGlowImages={}
	local dialHighlightImages={}
	local dialCenterCap=nil
	local fallbackSlices={}
	local currentPage=nil
	local pageTweens={}
	local paintTweens=setmetatable({}, {__mode="k"})
	local section=nil
	local sectionControls=nil
	local destroyConn=nil
	local connections={}
	local destroyed=false

	local function disconnect(connection)
		if safeDisconnect then
			safeDisconnect(connection)
		elseif connection then
			pcall(function()
				connection:Disconnect()
			end)
		end
	end

	local function trackConnection(connection)
		connections[#connections+1]=connection
		return connection
	end

	local function disconnectConnections()
		for _,connection in ipairs(connections) do
			disconnect(connection)
		end

		table.clear(connections)
	end

	local function accentColor()
		return themeColor(colors,"SLIDER_FILL",themeColor(colors,"ACC",themeColor(colors,"GREEN",Color3.fromRGB(32,202,106))))
	end

	local function inputColor()
		return themeColor(colors,"INPUT",themeColor(colors,"PANEL",Color3.fromRGB(33,33,33)))
	end

	local function mutedColor()
		return themeColor(colors,"MUTED",Color3.fromRGB(168,168,168))
	end

	local function textColor()
		return themeColor(colors,"TEXT",Color3.fromRGB(225,225,225))
	end

	local function normalizeState()
		if runtime.Refresh then runtime.Refresh() end
	end

	local paintDial=nil
	local showPage=nil

	local function syncControls(reason)
		if gravitySlider then gravitySlider.set(state.gravityValue) end
		if speedSlider then speedSlider.set(state.speedValue) end
		if staminaRegenSlider then staminaRegenSlider.set(state.staminaRegenValue) end
		if staminaDepleteSlider then staminaDepleteSlider.set(state.staminaDepleteValue) end
		if jumpSlider then jumpSlider.set(state.jumpPowerValue) end
		if diveSlider then diveSlider.set(state.divePowerValue) end
		for settingKey,toggle in pairs(settingToggles) do
			if toggle and toggle.set then
				toggle.set(state[settingKey]==true,false)
			end
		end
		if paintDial then paintDial(reason=="page" or reason=="page-toggle" or reason=="hover") end
		if showPage then showPage(state.paramsSelectedPage,reason=="page" or reason=="page-toggle") end
	end

	local function delegate(method,...)
		local fn=runtime and runtime[method]
		if type(fn)=="function" then
			return fn(...)
		end
	end

	function api.SetGravityState(...)
		return delegate("SetGravityState",...)
	end

	function api.SetGravityValue(...)
		return delegate("SetGravityValue",...)
	end

	function api.SetSpeedState(...)
		return delegate("SetSpeedState",...)
	end

	function api.SetSpeedValue(...)
		return delegate("SetSpeedValue",...)
	end

	function api.SetParamsSelectedPage(...)
		return delegate("SetParamsSelectedPage",...)
	end

	function api.ActivateParamsPage(...)
		return delegate("ActivateParamsPage",...)
	end

	function api.SetParamsPageEnabled(...)
		return delegate("SetParamsPageEnabled",...)
	end

	function api.SetParamSettingEnabled(...)
		return delegate("SetParamSettingEnabled",...)
	end

	function api.SetGameParamsState(...)
		return delegate("SetGameParamsState",...)
	end

	function api.SetStaminaRegenValue(...)
		return delegate("SetStaminaRegenValue",...)
	end

	function api.SetStaminaDepleteValue(...)
		return delegate("SetStaminaDepleteValue",...)
	end

	function api.SetJumpPowerValue(...)
		return delegate("SetJumpPowerValue",...)
	end

	function api.SetDivePowerValue(...)
		return delegate("SetDivePowerValue",...)
	end
	local function cancelPageTweens()
		for _,tween in ipairs(pageTweens) do
			pcall(function()
				tween:Cancel()
			end)
		end

		table.clear(pageTweens)
	end

	local function cancelPaintTweens()
		for _,tween in pairs(paintTweens) do
			pcall(function()
				tween:Cancel()
			end)
		end

		table.clear(paintTweens)
	end

	local function tweenObject(object,goal,tweenInfo)
		if not object then return nil end

		local oldTween=paintTweens[object]
		if oldTween then
			pcall(function()
				oldTween:Cancel()
			end)
		end

		local tween=TweenService:Create(object,tweenInfo or paintTween,goal)
		paintTweens[object]=tween
		tween.Completed:Connect(function()
			if paintTweens[object]==tween then
				paintTweens[object]=nil
			end
		end)
		tween:Play()
		return tween
	end

	paintDial=function(animate)
		local selected=normalizePageKey(state.paramsSelectedPage)
		local activeBase=accentColor()
		local surface=themeColor(colors,"PANEL",themeColor(colors,"BG",Color3.fromRGB(12,12,12)))
		local lightTheme=colorLuminance(surface)>0.70
		local active=lightTheme and darkenColor(activeBase,0.28) or activeBase
		local coreColor=lightTheme and darkenColor(active,0.04) or brightenColor(active,0.04)
		local muted=mutedColor()

		for _,pageKey in ipairs(pageOrder) do
			local isSelected=pageKey==selected
			local targetColor=isSelected and coreColor or muted
			local targetTransparency=isSelected and 0.10 or 0.70
			local highlightTransparency=isSelected and (lightTheme and 0.88 or 0.84) or 1
			local nearGlowTransparency=isSelected and 0.54 or 1
			local midGlowTransparency=isSelected and 0.78 or 1
			local farGlowTransparency=1
			local outerGlowTransparency=1
			local haloColor=lightTheme and darkenColor(coreColor,0.10) or brightenColor(coreColor,0.16)
			local highlightColor=lightTheme and Color3.new(0,0,0) or Color3.new(1,1,1)

			if dialImages[pageKey] then
				if animate then
					tweenObject(dialImages[pageKey],{ImageColor3=targetColor,ImageTransparency=targetTransparency})
				else
					dialImages[pageKey].ImageColor3=targetColor
					dialImages[pageKey].ImageTransparency=targetTransparency
				end
			end

			if dialHighlightImages[pageKey] then
				if animate then
					tweenObject(dialHighlightImages[pageKey],{ImageColor3=highlightColor,ImageTransparency=highlightTransparency},glowTween)
				else
					dialHighlightImages[pageKey].ImageColor3=highlightColor
					dialHighlightImages[pageKey].ImageTransparency=highlightTransparency
				end
			end

			if dialGlowImages[pageKey] then
				for index,glow in ipairs(dialGlowImages[pageKey]) do
					local glowTransparency=index==1 and nearGlowTransparency or (index==2 and midGlowTransparency or (index==3 and farGlowTransparency or outerGlowTransparency))
					if animate then
						tweenObject(glow,{ImageColor3=haloColor,ImageTransparency=glowTransparency},glowTween)
					else
						glow.ImageColor3=haloColor
						glow.ImageTransparency=glowTransparency
					end
				end
			end

			if fallbackSlices[pageKey] then
				if animate then
					tweenObject(fallbackSlices[pageKey],{BackgroundColor3=targetColor,BackgroundTransparency=targetTransparency})
				else
					fallbackSlices[pageKey].BackgroundColor3=targetColor
					fallbackSlices[pageKey].BackgroundTransparency=targetTransparency
				end
			end
		end

		if dialCenterCap then
			local capColor=inputColor()
			if animate then
				tweenObject(dialCenterCap,{ImageColor3=capColor})
			else
				dialCenterCap.ImageColor3=capColor
			end
		end
	end

	showPage=function(pageKey,animate)
		pageKey=normalizePageKey(pageKey)

		if currentPage==pageKey and pageFrames[pageKey] then
			for key,frame in pairs(pageFrames) do
				frame.Visible=key==pageKey
				frame.Position=UDim2.fromScale(key==pageKey and 0 or 1,0)
			end
			return
		end

		local oldPage=currentPage
		local oldFrame=oldPage and pageFrames[oldPage] or nil
		local newFrame=pageFrames[pageKey]
		if not newFrame then return end

		cancelPageTweens()

		local dir=1
		if oldPage and pageIndex[pageKey] and pageIndex[oldPage] and pageIndex[pageKey]<pageIndex[oldPage] then
			dir=-1
		end

		currentPage=pageKey
		newFrame.Visible=true

		if not animate or not oldFrame then
			for key,frame in pairs(pageFrames) do
				frame.Visible=key==pageKey
				frame.Position=UDim2.fromScale(key==pageKey and 0 or 1,0)
			end
			return
		end

		oldFrame.Visible=true
		oldFrame.Position=UDim2.fromScale(0,0)
		newFrame.Position=UDim2.fromScale(dir,0)

		local oldTween=TweenService:Create(oldFrame,pageTween,{Position=UDim2.fromScale(-dir,0)})
		local newTween=TweenService:Create(newFrame,pageTween,{Position=UDim2.fromScale(0,0)})
		table.insert(pageTweens,oldTween)
		table.insert(pageTweens,newTween)
		oldTween:Play()
		newTween:Play()
		oldTween.Completed:Connect(function()
			if oldFrame and oldFrame.Parent and currentPage==pageKey then
				oldFrame.Visible=false
			end
		end)
	end

	local function createDial(parentFrame)
		dialWrap=make("Frame",{
			AnchorPoint=Vector2.new(1,0),
			BackgroundTransparency=1,
			Position=UDim2.new(1,0,0,0),
			Size=UDim2.fromOffset(dialWidth+dialGlowPad*2,dialHeight+dialGlowPad*2),
			ZIndex=6,
			ClipsDescendants=false,
		},parentFrame)

		local canvas=make("Frame",{
			AnchorPoint=Vector2.new(0,0),
			Position=UDim2.fromOffset(dialGlowPad,dialGlowPad),
			Size=UDim2.fromOffset(dialWidth,dialHeight),
			BackgroundTransparency=1,
			ClipsDescendants=false,
			ZIndex=6,
		},dialWrap)

		local assets=getDialSliceAssets()
		local function pageAtPosition(position)
			local absoluteSize=canvas.AbsoluteSize
			local x,y
			if type(app.objectLocalPointer)=="function" then
				x,y=app.objectLocalPointer(canvas,position)
			else
				local absolutePosition=canvas.AbsolutePosition
				x=(position.X or 0)-absolutePosition.X
				y=(position.Y or 0)-absolutePosition.Y
			end
			local size=math.min(absoluteSize.X,absoluteSize.Y)

			if size<=0 then
				return nil
			end

			local dx=x-absoluteSize.X*0.5
			local dy=y-absoluteSize.Y*0.5
			local radius=math.sqrt(dx*dx+dy*dy)
			local inner=size*dialInnerRadius
			local outer=size*dialOuterRadius

			if radius<inner or radius>outer then
				return nil
			end

			local angle=math.deg(atan2(-dy,dx))
			if angle<0 then
				angle=angle+360
			end

			for _,sector in ipairs(dialSectors) do
				if inAngleRange(angle,sector.start,sector.finish) then
					return sector.key
				end
			end

			return nil
		end

		for _,pageKey in ipairs(pageOrder) do
			local sliceData=dialSliceData[pageKey]
			local pageAssets=assets and assets[pageKey]
			if pageAssets and pageAssets.slice and pageAssets.glow and sliceData then
				dialGlowImages[pageKey]={}
				for _,layer in ipairs(dialGlowLayers) do
					local pad=layer.pad
					local glow=make("ImageLabel",{
						BackgroundTransparency=1,
						Position=UDim2.new(sliceData.x,-pad,sliceData.y,-pad),
						Size=UDim2.new(sliceData.w,pad*2,sliceData.h,pad*2),
						Image=pageAssets.glow,
						ImageColor3=inputColor(),
						ImageTransparency=1,
						ResampleMode=Enum.ResamplerMode.Default,
						ScaleType=Enum.ScaleType.Stretch,
						ZIndex=layer.z,
					},canvas)
					table.insert(dialGlowImages[pageKey],glow)
				end

				dialImages[pageKey]=make("ImageLabel",{
					BackgroundTransparency=1,
					Position=UDim2.fromScale(sliceData.x,sliceData.y),
					Size=UDim2.fromScale(sliceData.w,sliceData.h),
					Image=pageAssets.slice,
					ImageColor3=inputColor(),
					ImageTransparency=0.34,
					ResampleMode=Enum.ResamplerMode.Default,
					ScaleType=Enum.ScaleType.Stretch,
					ZIndex=6,
				},canvas)

				dialHighlightImages[pageKey]=make("ImageLabel",{
					BackgroundTransparency=1,
					Position=UDim2.fromScale(sliceData.x,sliceData.y),
					Size=UDim2.fromScale(sliceData.w,sliceData.h),
					Image=pageAssets.slice,
					ImageColor3=Color3.new(1,1,1),
					ImageTransparency=1,
					ResampleMode=Enum.ResamplerMode.Default,
					ScaleType=Enum.ScaleType.Stretch,
					ZIndex=7,
				},canvas)
			else
				local angle=dialMidAngles[pageKey] or 90
				local radians=math.rad(angle)
				local midRadius=dialWidth*(dialInnerRadius+dialOuterRadius)*0.5
				local fallback=make("Frame",{
					AnchorPoint=Vector2.new(0.5,0.5),
					Position=UDim2.new(0.5,math.cos(radians)*midRadius,0.5,-math.sin(radians)*midRadius),
					Size=UDim2.fromOffset(30,18),
					Rotation=90-angle,
					BackgroundColor3=inputColor(),
					BackgroundTransparency=0.34,
					BorderSizePixel=0,
					ZIndex=6,
					ThemeRole="INPUT",
				},canvas)
				fallbackSlices[pageKey]=fallback
			end
		end

		if assets and assets._center then
			local centerSize=math.floor(dialWidth*dialInnerRadius*2+8)
			dialCenterCap=make("ImageLabel",{
				AnchorPoint=Vector2.new(0.5,0.5),
				Position=UDim2.fromScale(0.5,0.5),
				Size=UDim2.fromOffset(centerSize,centerSize),
				BackgroundTransparency=1,
				Image=assets._center,
				ImageColor3=inputColor(),
				ImageTransparency=0.03,
				ResampleMode=Enum.ResamplerMode.Default,
				ScaleType=Enum.ScaleType.Stretch,
				ZIndex=8,
			},canvas)
		end

		local hitLayer=make("TextButton",{
			Position=UDim2.fromScale(0,0),
			Size=UDim2.fromScale(1,1),
			BackgroundTransparency=1,
			BorderSizePixel=0,
			Text="",
			AutoButtonColor=false,
			Selectable=false,
			ZIndex=10,
		},canvas)

		trackConnection(hitLayer.InputBegan:Connect(function(input)
			if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then
				return
			end

			local pageKey=pageAtPosition(input.Position)
			if pageKey then
				api.ActivateParamsPage(pageKey,true)
			end
		end))

	end

	local function createPageEditor(parentFrame)
		local paramsRow=make("Frame",{
			BackgroundTransparency=1,
			Size=UDim2.new(1,0,0,paramsPageHeight),
			LayoutOrder=1,
			ClipsDescendants=false,
			ZIndex=6,
		},parentFrame)

		pageClip=make("Frame",{
			BackgroundTransparency=1,
			Size=UDim2.new(1,-(dialWidth+dialSideGap+dialGlowPad*2),0,paramsPageHeight),
			ClipsDescendants=true,
			ZIndex=6,
		},paramsRow)
		createDial(paramsRow)

		for _,pageKey in ipairs(pageOrder) do
			local page=make("Frame",{
				BackgroundTransparency=1,
				Position=UDim2.fromScale(1,0),
				Size=UDim2.fromScale(1,1),
				Visible=false,
				ZIndex=6,
			},pageClip)
			make("UIListLayout",{Padding=UDim.new(0,6),SortOrder=Enum.SortOrder.LayoutOrder},page)
			pageFrames[pageKey]=page
		end

		local function buildSettingSlider(page,settingKey,label,min,max,start,decimals,onChange)
			if buildToggleLabel then
				settingToggles[settingKey]=buildToggleLabel(page,label,state[settingKey]==true,function(value)
					api.SetParamSettingEnabled(settingKey,value,true)
				end)
			elseif buildToggleRow then
				settingToggles[settingKey]=buildToggleRow(page,label,state[settingKey]==true,function(value)
					api.SetParamSettingEnabled(settingKey,value,true)
				end)
			end

			return buildSlider(page,(buildToggleLabel or buildToggleRow) and "" or label,min,max,start,decimals,onChange)
		end

		speedSlider=buildSettingSlider(pageFrames.speed,"speedSettingEnabled","Speed",0,100,state.speedValue,0,function(v)
			api.SetSpeedValue(v,true)
		end)

		diveSlider=buildSettingSlider(pageFrames.speed,"diveSettingEnabled","Dive",0,15,state.divePowerValue,2,function(v)
			api.SetDivePowerValue(v,true)
		end)

		gravitySlider=buildSettingSlider(pageFrames.gravity,"gravitySettingEnabled","Gravity",0,1000,state.gravityValue,1,function(v)
			api.SetGravityValue(v,true)
		end)

		jumpSlider=buildSettingSlider(pageFrames.gravity,"jumpPowerSettingEnabled","Jump Power",0,300,state.jumpPowerValue,1,function(v)
			api.SetJumpPowerValue(v,true)
		end)

		staminaDepleteSlider=buildSettingSlider(pageFrames.stamina,"staminaDepleteSettingEnabled","Stamina Depletion",0,50,state.staminaDepleteValue,0,function(v)
			api.SetStaminaDepleteValue(v,true)
		end)

		staminaRegenSlider=buildSettingSlider(pageFrames.stamina,"staminaRegenSettingEnabled","Stamina Regeneration",0,50,state.staminaRegenValue,1,function(v)
			api.SetStaminaRegenValue(v,true)
		end)
	end

	normalizeState()
	section,sectionControls=makeSection(parent,2,"Game Params","")

	createPageEditor(section)

	if runtime.SetOnStateChanged then
		runtime.SetOnStateChanged(function(_,reason)
			syncControls(reason)
			task.defer(function()
				if not destroyed then
					syncControls(reason)
				end
			end)
		end)
	end

	function api.Refresh()
		delegate("Refresh")
		syncControls()
	end

	function api.Reset()
		delegate("Reset")
		syncControls()
	end

	function api.Destroy()
		if destroyed then return end
		destroyed=true
		disconnect(destroyConn)
		destroyConn=nil
		destroyControl(gravitySlider)
		destroyControl(speedSlider)
		destroyControl(staminaRegenSlider)
		destroyControl(staminaDepleteSlider)
		destroyControl(jumpSlider)
		destroyControl(diveSlider)
		for _,toggle in pairs(settingToggles) do
			destroyControl(toggle)
		end
		table.clear(settingToggles)
		cancelPageTweens()
		cancelPaintTweens()
		disconnectConnections()
		if runtime.SetOnStateChanged then
			runtime.SetOnStateChanged(nil)
		end
		if runtime.Destroy then
			runtime.Destroy()
		end
	end

	destroyConn=section.AncestryChanged:Connect(function()
		if section.Parent==nil then
			api.Destroy()
		end
	end)

	api.Refresh()

	return api
end

return gameParamsGui
